import { getHomePageData } from "@/content/api";
import { BmiCalculator, toBmiProps } from "@/features/bmi";
import { FaqSection, toFaqProps } from "@/features/faq";
import {
  ClosingCta,
  SiteFooter,
  toClosingCtaProps,
  toFooterProps,
} from "@/features/footer";
import { Hero, toHeroProps } from "@/features/hero";
import { HowItWorks, toHowItWorksProps } from "@/features/how-it-works";
import { SiteHeader, toNavigationProps } from "@/features/navigation";
import { ServicesCarousel, toOnlineCareProps } from "@/features/online-care";
import { ProgramSection, toProgramSectionsProps } from "@/features/programs";
import { SuccessStories, toStoriesProps } from "@/features/stories";
import { TrustStrip } from "@/features/trust-strip";

/**
 * Home page: fetch all content once (server), map it to each section's
 * props and render the sections in order.
 */
export default async function HomePage() {
  const data = await getHomePageData();
  const programSections = toProgramSectionsProps(
    data.home,
    data.programs,
    data.products,
  );
  const { programId: bmiHost, ...bmi } = toBmiProps(data.home);
  const onlineCare = toOnlineCareProps(data.home, data.services);
  const stories = toStoriesProps(data.home, data.testimonials, data.programs);
  const faq = toFaqProps(data.home, data.faqs);

  return (
    <>
      <SiteHeader {...toNavigationProps(data.home, data.programs)} />
      <main>
        <Hero {...toHeroProps(data.home, data.programs, data.languages)} />
        <TrustStrip items={data.home.trustStrip.items} />
        <HowItWorks {...toHowItWorksProps(data.home)} />
        <div className="flex flex-col gap-program-gap pb-section-y">
          {programSections.map((section) => (
            <ProgramSection key={section.id} {...section}>
              {section.id === bmiHost ? <BmiCalculator {...bmi} /> : null}
            </ProgramSection>
          ))}
        </div>
        {onlineCare.services.length > 0 ? (
          <ServicesCarousel {...onlineCare} />
        ) : null}
        {stories.stories.length > 0 ? <SuccessStories {...stories} /> : null}
        {faq.items.length > 0 ? <FaqSection {...faq} /> : null}
        <ClosingCta {...toClosingCtaProps(data.home)} />
      </main>
      <SiteFooter
        {...toFooterProps(data.home, data.programs, new Date().getFullYear())}
      />
    </>
  );
}
import { z } from "zod";
import * as mock from "../mock";
import {
  type Faq,
  FaqList,
  type HomeContent,
  HomeContent as HomeContentSchema,
  type Language,
  LanguageList,
  type Product,
  ProductList,
  type Program,
  ProgramList,
  type Service,
  ServiceList,
  type Testimonial,
  TestimonialList,
} from "../schemas";

/**
 * Data access: the only place that knows where content comes from.
 *
 * - `mock` (default): returns the mock responses, still validated against
 *   the schemas so mocks cannot drift from the contract.
 * - `api`: GET `${baseUrl}${path}` and validate the JSON. Written against
 *   the contract but UNVERIFIED: no backend exists yet; tests use a fake
 *   fetch.
 *
 * Swapping to the real backend means setting DATA_SOURCE=api and
 * API_BASE_URL; components never change.
 */

const endpoints = {
  home: {
    path: "/content/home",
    schema: HomeContentSchema,
    mock: mock.homeContent,
  },
  programs: { path: "/programs", schema: ProgramList, mock: mock.programs },
  products: { path: "/products", schema: ProductList, mock: mock.products },
  languages: { path: "/languages", schema: LanguageList, mock: mock.languages },
  services: { path: "/services", schema: ServiceList, mock: mock.services },
  testimonials: {
    path: "/testimonials",
    schema: TestimonialList,
    mock: mock.testimonials,
  },
  faqs: { path: "/faqs", schema: FaqList, mock: mock.faqs },
} as const;

export type ResourceName = keyof typeof endpoints;

type ResourceMap = {
  home: HomeContent;
  programs: Program[];
  products: Product[];
  languages: Language[];
  services: Service[];
  testimonials: Testimonial[];
  faqs: Faq[];
};

export class ContentError extends Error {
  constructor(
    readonly resource: ResourceName,
    message: string,
    options?: { cause?: unknown },
  ) {
    super(`[content:${resource}] ${message}`, options);
    this.name = "ContentError";
  }
}

export type DataSource = "mock" | "api";

export type ContentClientOptions = {
  source: DataSource;
  /** Required when source is "api". */
  baseUrl?: string;
  /** Injected for tests; defaults to global fetch. */
  fetch?: typeof fetch;
};

/** Everything the home page needs. Optional resources degrade to []. */
export type HomePageData = ResourceMap & {
  /** Resources that failed and were replaced by an empty list. */
  degraded: { resource: ResourceName; reason: string }[];
};

export function createContentClient(options: ContentClientOptions) {
  const doFetch = options.fetch ?? fetch;

  async function getResource<K extends ResourceName>(
    name: K,
  ): Promise<ResourceMap[K]> {
    const endpoint = endpoints[name];
    let raw: unknown;

    if (options.source === "mock") {
      raw = endpoint.mock;
    } else {
      if (!options.baseUrl) {
        throw new ContentError(name, "API_BASE_URL is not set");
      }
      const response = await doFetch(`${options.baseUrl}${endpoint.path}`, {
        headers: { Accept: "application/json" },
      });
      if (!response.ok) {
        throw new ContentError(name, `HTTP ${response.status}`);
      }
      raw = await response.json();
    }

    const parsed = endpoint.schema.safeParse(raw);
    if (!parsed.success) {
      throw new ContentError(name, z.prettifyError(parsed.error), {
        cause: parsed.error,
      });
    }
    // The schema for `name` produces ResourceMap[K]; TypeScript cannot
    // correlate the generic key with the union of schemas.
