"use client";

import {
  type AnimationPlaybackControls,
  animate,
  useReducedMotion,
} from "motion/react";
import { useCallback, useEffect, useId, useRef, useState } from "react";
import { ArrowRightCircleIcon } from "@/components/icons";
import { IconButton } from "@/components/ui/icon-button";
