        <ul className="hidden items-center gap-4 justify-self-center nav:flex">
          {items.map((item) => (
            <li key={item.id}>
              <NavLink
                item={item}
                active={
                  item.sectionId !== null && item.sectionId === activeSectionId
                }
              />
            </li>
