import { expect, test } from "@playwright/test";

/**
 * Assignment 4B "responsive floor": at every width from 320 to 1920 the
 * page must not overflow horizontally. We resize one loaded page through
 * every width (step configurable via RESPONSIVE_STEP, default 1px) and
 * collect the widths where the document is wider than the viewport,
 * together with the elements sticking out, so failures are actionable.
 */
const MIN_WIDTH = 320;
const MAX_WIDTH = 1920;
const HEIGHT = 900;
const STEP = Number(process.env.RESPONSIVE_STEP ?? 1);

type Overflow = { width: number; scrollWidth: number; culprits: string[] };

test("no horizontal overflow from 320px to 1920px", async ({ page }) => {
  test.setTimeout(600_000);
  await page.setViewportSize({ width: MIN_WIDTH, height: HEIGHT });
  await page.goto("/");
  await page.waitForLoadState("networkidle");

  const failures: Overflow[] = [];

  for (let width = MIN_WIDTH; width <= MAX_WIDTH; width += STEP) {
    await page.setViewportSize({ width, height: HEIGHT });
    const result = await page.evaluate((viewport) => {
      const root = document.documentElement;
      if (root.scrollWidth <= viewport) return null;
      // Elements sticking out of the viewport that are NOT clipped by an
      // ancestor (overflow hidden/clip), i.e. the ones that cause scrolling.
      const clipped = (el: Element) => {
        for (
          let p = el.parentElement;
          p && p !== document.body;
          p = p.parentElement
        ) {
          const { overflowX } = getComputedStyle(p);
          if (overflowX === "hidden" || overflowX === "clip") {
            const r = p.getBoundingClientRect();
            if (r.right <= viewport + 0.5 && r.left >= -0.5) return true;
          }
        }
        return false;
      };
      const culprits: string[] = [];
      for (const el of document.body.querySelectorAll<HTMLElement>("*")) {
        const rect = el.getBoundingClientRect();
        if ((rect.right > viewport + 0.5 || rect.left < -0.5) && !clipped(el)) {
          const id = el.id ? `#${el.id}` : "";
          const cls = el.classList.length
            ? `.${[...el.classList].slice(0, 4).join(".")}`
            : "";
          culprits.push(
            `${el.tagName.toLowerCase()}${id}${cls} right=${Math.round(rect.right)}`,
          );
          if (culprits.length >= 6) break;
        }
      }
      return { scrollWidth: root.scrollWidth, culprits };
    }, width);
    if (result) failures.push({ width, ...result });
  }

  expect(failures, JSON.stringify(failures.slice(0, 10), null, 2)).toEqual([]);
});
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";

/**
 * Whole-page accessibility checks: an axe scan (WCAG 2.x A / AA) on both
 * boards and a keyboard walk that tabs through the page.
 *
 * Known, logged contrast exceptions (README "Noted, not changed"):
 * - hero badges (`text-accent-soft`, #21ac88 on white, ~2.9:1), kept for
 *   fidelity until the colour pass (C10);
 * - the big "01" / "02" in How it works (`text-step-number`): decorative and
 *   aria-hidden (the ordered list announces the order), exempt under 1.4.3.
 */
const KNOWN_CONTRAST = /text-accent-soft|text-step-number/;

for (const width of [375, 1440]) {
  test(`axe finds no WCAG A/AA violations at ${width}px`, async ({ page }) => {
    await page.setViewportSize({ width, height: 900 });
    await page.goto("/");
    const { violations } = await new AxeBuilder({ page })
      .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
      .analyze();

    const unexpected = violations.flatMap((violation) =>
      violation.nodes
        .filter(
          (node) =>
            !(
              violation.id === "color-contrast" &&
              node.target.join(" ").match(KNOWN_CONTRAST)
            ),
        )
        .map((node) => `${violation.id}: ${node.target.join(" ")}`),
    );
    expect(unexpected).toEqual([]);
  });
}

test("tabbing reaches every control in order with a visible focus ring", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto("/");

  const seen: string[] = [];
  for (let step = 0; step < 200; step += 1) {
    await page.keyboard.press("Tab");
    // Smooth scrolling brings the focused element in over a few frames.
    await page
      .waitForFunction(
        () => {
          const el = document.activeElement;
          if (!el || el === document.body) return true;
          const box = el.getBoundingClientRect();
          return box.bottom > 0 && box.top < window.innerHeight;
        },
        undefined,
        { timeout: 1500 },
      )
      .catch(() => undefined);
    const info = await page.evaluate(() => {
      const el = document.activeElement as HTMLElement | null;
      if (!el || el === document.body) return null;
      // The ring is drawn on the element or, for inputs inside a styled
      // field, on its wrapper (`has-[input:focus-visible]`).
      const ringOn = (node: Element | null) =>
        node instanceof HTMLElement &&
        getComputedStyle(node).outlineStyle !== "none" &&
        getComputedStyle(node).outlineWidth !== "0px";
      const box = el.getBoundingClientRect();
      return {
        name: `${el.tagName.toLowerCase()} ${el.getAttribute("aria-label") ?? el.textContent?.trim().slice(0, 40) ?? ""}`,
        ring:
          ringOn(el) ||
          ringOn(el.parentElement) ||
          ringOn(el.parentElement?.parentElement ?? null),
        visible:
          box.width > 0 &&
          box.height > 0 &&
          box.bottom > 0 &&
          box.top < window.innerHeight,
        // The page footer, not the <footer> inside testimonial cards.
        inFooter: Boolean(el.closest("footer") && !el.closest("article")),
      };
    });
    if (!info) break;
    expect.soft(info.ring, `focus ring on ${info.name}`).toBe(true);
    expect.soft(info.visible, `${info.name} scrolled into view`).toBe(true);
    seen.push(info.name);
    if (info.inFooter && info.name.includes("on LinkedIn")) break;
  }

  // The walk starts in the nav and ends at the footer socials, passing the
  // main interactive sections on the way.
  const joined = seen.join("\n");
  for (const expected of [
    "Apsu home",
    // "Calculate BMI" is skipped: it stays disabled until the input is valid.
    "Height, feet",
    "Next",
    "on Instagram",
    "What states do you serve",
    "Start a free consultation",
    "FAQs",
    "APSU on LinkedIn",
  ]) {
    expect(joined).toContain(expected);
  }
});
