import { z } from "zod";

/**
 * Shared building blocks of the API contract.
 *
 * Conventions (doc/architecture.md §2.5):
 * - Objects use z.object, which ignores unknown keys, so the backend can add
 *   fields without breaking the front end.
 * - Content only: no colours, layout or CSS. Presentation is derived on the
 *   front end (e.g. `category` -> theme).
 * - Stable string ids; references between resources use those ids.
 * - Open string sets (categories, icon keys) stay `string` so an unknown
 *   value falls back to a default instead of failing validation.
 */

/** Stable identifier (slug-like). */
export const Id = z.string().min(1);

/**
 * Where a control leads. `none` = no destination yet: the control only gives
 * press feedback (decisions Q1/Q2/C3).
 */
export const Link = z.discriminatedUnion("type", [
  /** Same-page section, e.g. "weight-loss" -> #weight-loss. */
  z.object({ type: z.literal("anchor"), target: Id }),
  /** In-app route for future pages, e.g. "/login". */
  z.object({ type: z.literal("route"), path: z.string().startsWith("/") }),
  z.object({ type: z.literal("external"), url: z.url() }),
  z.object({ type: z.literal("none") }),
]);

export const Cta = z.object({
  label: z.string().min(1),
  link: Link,
});

/** Text with optional emphasised (highlighted) runs and inline links. */
export const RichTextSegment = z.object({
  text: z.string(),
  emphasis: z.boolean().optional(),
  link: Link.optional(),
});
export const RichText = z.array(RichTextSegment).min(1);

/** Image reference. Dimensions are the intrinsic size of the file. */
export const Image = z.object({
  src: z.string().min(1),
  alt: z.string(),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
});

/** Money in minor units (cents) + ISO 4217 currency; formatted with Intl. */
export const Money = z.object({
  amountMinor: z.number().int().nonnegative(),
  currency: z.string().length(3),
});

export const BillingInterval = z.enum(["week", "month", "year"]);

/** "From $20/mo". */
export const RecurringPrice = Money.extend({ interval: BillingInterval });

/**
 * Icon key resolved by the front end's icon map (e.g. "truck",
 * "stethoscope"). Unknown keys render without an icon.
 */
export const IconKey = z.string().min(1);

/** Short icon + label claim (hero badges, trust strip). */
export const TrustItem = z.object({
  id: Id,
  icon: IconKey,
  label: z.string().min(1),
});

export const SocialPlatform = z.enum([
  "x",
  "instagram",
  "linkedin",
  "facebook",
]);

export const SocialProfile = z.object({
  platform: SocialPlatform,
  url: z.url(),
});

export type Id = z.infer<typeof Id>;
export type RichTextSegment = z.infer<typeof RichTextSegment>;
export type RichText = z.infer<typeof RichText>;
export type Link = z.infer<typeof Link>;
export type Cta = z.infer<typeof Cta>;
export type Image = z.infer<typeof Image>;
export type Money = z.infer<typeof Money>;
export type BillingInterval = z.infer<typeof BillingInterval>;
export type RecurringPrice = z.infer<typeof RecurringPrice>;
export type IconKey = z.infer<typeof IconKey>;
export type TrustItem = z.infer<typeof TrustItem>;
export type SocialPlatform = z.infer<typeof SocialPlatform>;
export type SocialProfile = z.infer<typeof SocialProfile>;
import { z } from "zod";
import { Cta, Id, Image, RecurringPrice, RichText } from "./common";

/**
 * GET /programs — the care programs (weight loss, birth control, sleep).
 *
 * A program is the single source for its name and copy: navigation, the
 * footer, hero category cards and testimonials reference it by id instead of
 * repeating the text.
 */

/** Decorative stat card over the program image (sleep section). */
export const HighlightCard = z.discriminatedUnion("kind", [
  /** "Olivia Gomes — 78 Normal · 89.5% Progress" */
  z.object({
    kind: z.literal("metrics"),
    id: Id,
    title: z.string().min(1),
    metrics: z
      .array(z.object({ value: z.string().min(1), label: z.string().min(1) }))
      .min(1),
  }),
  /** "Your profile — 82%" with a progress bar. */
  z.object({
    kind: z.literal("progress"),
    id: Id,
    title: z.string().min(1),
    /** 0–100 */
    percent: z.number().min(0).max(100),
  }),
]);

export const Program = z.object({
  id: Id,
  /**
   * Drives the front-end theme (mint / purple / blue). Open set: unknown
   * categories render with the default theme.
   */
  category: z.string().min(1),
  /** Short name used in nav, footer and as the section eyebrow: "Weight Loss". */
  name: z.string().min(1),
  /** Summary card in the hero. */
  card: z.object({
    eyebrow: z.string().min(1),
    title: z.string().min(1),
    image: Image,
  }),
  /** Full section further down the page. */
  section: z.object({
    /** Show `name` as an eyebrow above the heading (only weight loss does). */
    showEyebrow: z.boolean(),
    heading: RichText,
    /** Paragraphs under the heading. */
    intro: z.array(z.string().min(1)),
    points: z.array(z.string().min(1)),
    /** Shown as "From $20/mo"; omitted when products carry the prices. */
    startingPrice: RecurringPrice.optional(),
    cta: Cta,
    image: Image,
    highlights: z.array(HighlightCard).optional(),
  }),
});

export const ProgramList = z.array(Program);

export type HighlightCard = z.infer<typeof HighlightCard>;
export type Program = z.infer<typeof Program>;
import { z } from "zod";
import { Id, Image } from "./common";

/**
 * GET /services — cards in the "Completely online on your schedule"
 * carousel. `media.kind` tells the front end which card layout to use.
 */

export const ChatMessage = z.object({
  id: Id,
  from: z.enum(["provider", "patient"]),
  text: z.string().min(1),
  /** Display time, e.g. "10:00 AM". */
  time: z.string().min(1),
});

export const ServiceMedia = z.discriminatedUnion("kind", [
  /** Full-bleed photo behind a white title. */
  z.object({ kind: z.literal("photo"), image: Image }),
  /** Product shot on a white card under the title. */
  z.object({ kind: z.literal("product"), image: Image }),
  /** Phone mockup with a chat preview drawn by the front end. */
  z.object({
    kind: z.literal("chat"),
    image: Image,
    chat: z.object({
      providerName: z.string().min(1),
      providerAvatar: Image,
      status: z.string().min(1),
      dayLabel: z.string().min(1),
      messages: z.array(ChatMessage).min(1),
    }),
  }),
]);

export const Service = z.object({
  id: Id,
  title: z.string().min(1),
  media: ServiceMedia,
});

export const ServiceList = z.array(Service);

export type ChatMessage = z.infer<typeof ChatMessage>;
export type ServiceMedia = z.infer<typeof ServiceMedia>;
export type Service = z.infer<typeof Service>;
import { z } from "zod";
import { createContentClient } from "./client";

export {
  type ContentClientOptions,
  ContentError,
  createContentClient,
  type DataSource,
  type HomePageData,
  type ResourceName,
} from "./client";
export { pickByIds } from "./pick-by-ids";

/**
 * Environment: DATA_SOURCE=mock|api (default mock), API_BASE_URL for api.
 * Validated so a typo fails loudly instead of silently using mocks.
 */
const env = z
  .object({
    DATA_SOURCE: z.enum(["mock", "api"]).default("mock"),
    API_BASE_URL: z.url().optional(),
  })
  .parse({
    DATA_SOURCE: process.env.DATA_SOURCE,
    API_BASE_URL: process.env.API_BASE_URL,
  });

const client = createContentClient({
  source: env.DATA_SOURCE,
  baseUrl: env.API_BASE_URL,
});

/** Single entry point used by the home page (server component). */
export const getHomePageData = client.getHomePageData;
import type { Link } from "@/content/schemas";

/**
 * Turn a content Link into an href, or null when there is no destination
 * yet (`none`): such controls render as buttons with press feedback only.
 */
export function hrefFor(link: Link): string | null {
  switch (link.type) {
    case "anchor":
      return `#${link.target}`;
    case "route":
      return link.path;
    case "external":
      return link.url;
    case "none":
      return null;
  }
}
import type { VariantProps } from "class-variance-authority";
import {
  Button,
  ButtonLink,
  type buttonVariants,
} from "@/components/ui/button";
import type { Cta } from "@/content/schemas";
import { hrefFor } from "./link";

type CtaButtonProps = VariantProps<typeof buttonVariants> & {
  cta: Cta;
  className?: string;
};

/**
 * Renders a content CTA: a link when it has a destination, otherwise a
 * button that only gives press feedback (decisions Q1 / C3).
 */
export function CtaButton({ cta, ...props }: CtaButtonProps) {
  const href = hrefFor(cta.link);
  return href ? (
    <ButtonLink href={href} {...props}>
      {cta.label}
    </ButtonLink>
  ) : (
    <Button {...props}>{cta.label}</Button>
  );
}

