  --radius-card: 1rem; /* 16: cards, BMI panels */
  --radius-panel: 0.75rem; /* 12: FAQ items */
  --radius-feature: 1.5rem; /* 24: program feature cards (sampled) */
  --radius-bubble: 0.5rem; /* 8: chat bubbles in the services carousel */

  /* ---- Shadows ----------------------------------------------------------- */
  --shadow-*: initial;
  --shadow-card: 0 4px 12px 0 rgb(2 31 24 / 0.06); /* category / BMI cards */
  --shadow-soft: 0 4px 21.6px 0 rgb(2 29 23 / 0.06); /* "card shadow 2" */
  --shadow-pill: 0 4px 5.15px 0 rgb(0 0 0 / 0.05); /* language pills */
  --shadow-raised: 0 4px 12px 0 rgb(2 34 39 / 0.08); /* expanded FAQ */
  /* "Card Shadow" effect style: layered, used on the floating nav bar */
  --shadow-layered:
