/*
 * Category themes. Data only carries `category`; the front end maps it to a
 * theme by setting data-theme on the section/card. Components use the
 * bg-theme-surface / border-theme-divider utilities, which read the runtime
 * --theme-* variables, so an unknown category falls back to :root defaults.
 */
:root {
  --theme-surface: var(--color-surface);
  --theme-divider: var(--color-border);
}

