  --shadow-soft: 0 4px 21.6px 0 rgb(2 29 23 / 0.06); /* "card shadow 2" */
  --shadow-pill: 0 4px 5.15px 0 rgb(0 0 0 / 0.05); /* language pills */
  --shadow-raised: 0 4px 12px 0 rgb(2 34 39 / 0.08); /* expanded FAQ */
  /* "Card Shadow" effect style: layered, used on the floating nav bar */
  --shadow-layered:
    1px 1px 2px 0 rgb(0 0 0 / 0.1), 2px 3px 4px 0 rgb(0 0 0 / 0.09),
    5px 7px 5px 0 rgb(0 0 0 / 0.05), 9px 13px 6px 0 rgb(0 0 0 / 0.01);

  /* ---- Motion ------------------------------------------------------------ */
  /* "Fast then slow" settle used for carousel steps and reveals. */
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  /* Trust strip: endless leftward scroll (track = two identical copies). */
  --animate-marquee: marquee 64s linear infinite;
  /* FAQ answers: height from Radix's measured content height. */
  --animate-accordion-down: accordion-down 300ms var(--ease-out-expo);
  --animate-accordion-up: accordion-up 200ms var(--ease-standard);

  @keyframes marquee {
    to {
      transform: translateX(-50%);
    }
  }
  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }
  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

@media (width >= 70rem) {
  :root {
    --spacing-nav: 3.75rem;
  }
}

/* BMI scale bar (design stops at 0 / 33.3 / 66.7 / 100%). */
:root {
  --gradient-bmi: linear-gradient(
    90deg,
    var(--color-bmi-under) 0%,
    var(--color-bmi-healthy) 33.333%,
    var(--color-bmi-over) 66.667%,
    var(--color-bmi-obese) 100%
  );
}

/* Motion durations (use as duration-(--duration-fast) etc.). */
:root {
  --duration-fast: 150ms; /* colour changes */
  --duration-base: 200ms; /* transforms: hover lift, press */
  --duration-slow: 300ms; /* accordion, menu, carousel step */
}

@layer base {
  html {
    scroll-behavior: smooth;
  }

  /*
   * Keep anchored sections and focused controls clear of the sticky nav.
   * Not `scroll-padding-top` on <html>: that also applies to the sticky
   * nav's own controls, so focusing them (a click on the menu button, or
   * focus returning to it when the menu closes) scrolled the page ~400px
   * and cut short the scroll to the chosen section.
   */
  main [id],
  :is(main, footer)
    :is(
      a[href],
      button,
      input,
      select,
      textarea,
      [tabindex]:not([tabindex="-1"])
    ) {
    scroll-margin-top: 6rem;
  }

  /* One consistent, visible focus ring for every interactive element. */

  :focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    /* biome-ignore-start lint/complexity/noImportantStyles: reduced-motion fallback must override every component transition */
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
    /* biome-ignore-end lint/complexity/noImportantStyles: end of reduced-motion block */
  }
}

/*
 * Category themes. Data only carries `category`; the front end maps it to a
 * theme by setting data-theme on the section/card. Components use the
 * bg-theme-surface / border-theme-divider utilities, which read the runtime
 * --theme-* variables, so an unknown category falls back to :root defaults.
 */
:root {
  --theme-surface: var(--color-surface);
  --theme-divider: var(--color-border);
}

[data-theme="weight-loss"] {
  --theme-surface: var(--color-card-mint);
  --theme-divider: var(--color-border-mint);
}

[data-theme="birth-control"] {
  --theme-surface: var(--color-card-purple);
  --theme-divider: var(--color-border-pink);
}

[data-theme="sleep"] {
  --theme-surface: var(--color-card-blue);
  --theme-divider: var(--color-border-blue);
}

@theme inline {
  --color-theme-surface: var(--theme-surface);
  --color-theme-divider: var(--theme-divider);
  --font-sans: var(--font-work-sans), ui-sans-serif, system-ui, sans-serif;
}

body {
  background-color: var(--color-page);
  color: var(--color-copy);
  font-family: var(--font-sans);
}

