import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/lib/cn";

export type PillProps = Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  "aria-pressed"
> & {
  selected?: boolean;
};

/**
 * Language pill from the hero. A toggle button: clicking highlights it
 * (visual selection only, decision C1). Pass `lang` / `dir` for scripts such
 * as Arabic so the label is read and rendered correctly.
 *
 * Self-designed states: hover = bubble pop (scale 1.05) + tint, pressed =
 * scale 0.96, focus = global ring, selected = the design's light-green fill.
 */
export function Pill({
  selected = false,
  className,
  type = "button",
  ...props
}: PillProps) {
  return (
    <button
      type={type}
      aria-pressed={selected}
      className={cn(
        "inline-flex shrink-0 items-center justify-center h-pill rounded-full border px-pill-x",
        "text-label whitespace-nowrap shadow-pill",
        "transition-[scale,background-color,border-color,color] duration-(--duration-base) ease-standard",
        "hover:scale-[1.05] active:scale-[0.96]",
        selected
          ? "border-selected bg-selected text-ink-780"
          : "border-selected bg-off-white text-ink-600 hover:bg-faq-tint",
        className,
      )}
      {...props}
    />
  );
}
import Image from "next/image";
import { Eyebrow } from "@/components/ui/eyebrow";
import { CtaButton } from "@/features/shared/CtaButton";
import type { CategoryCardProps } from "./to-hero-props";

/**
 * Hero category card. The whole card is the hit area: the "See plans"
 * button's ::after stretches over the card (one real control, no nested
 * interactives). Self-designed states: hover = bubble lift + softer shadow
 * + image grows slightly, pressed = small shrink, focus = the button ring.
 */
export function CategoryCard({
  category,
  eyebrow,
  title,
  image,
  cta,
}: CategoryCardProps) {
  return (
    <article
      data-theme={category}
      className={[
        "group/card relative isolate flex h-55 flex-col justify-between overflow-hidden rounded-card bg-theme-surface p-card-pad shadow-card",
        "transition-[translate,scale,box-shadow] duration-(--duration-base) ease-standard",
        "hover:-translate-y-1 hover:shadow-soft has-[button:active]:scale-[0.98] has-[a:active]:scale-[0.98]",
        "xl:h-105.25",
      ].join(" ")}
    >
      {/*
        Product shot (design fill geometry). Stacked cards (fixed 220px tall)
        use a fixed 337px image anchored right, so wider screens keep the
        mobile composition; the 3-column cards (from xl, where they are wide enough for the
        desktop proportions) use the design's percentages.
      */}
      <div className="pointer-events-none absolute -top-6.5 -right-26.75 -z-10 aspect-square w-84.25 xl:top-[3.1%] xl:right-auto xl:left-[7.8%] xl:w-[131%]">
        <Image
          src={image.src}
          alt={image.alt}
          fill
          sizes="(min-width: 80rem) 36vw, 21rem"
          className="object-contain transition-[scale] duration-(--duration-slow) ease-standard group-hover/card:scale-[1.04]"
        />
      </div>

      <div className="relative flex flex-col gap-2 xl:gap-4">
        <Eyebrow tone="heading" size="lg">
          {eyebrow}
        </Eyebrow>
        <h3 className="max-w-[12.5rem] text-title font-medium text-ink-800 sm:max-w-[60%] xl:max-w-[64%]">
          {title}
        </h3>
      </div>

      {cta ? (
        // Not positioned: the button's ::after must stretch over the article.
        <div className="pt-6">
          <CtaButton
            cta={cta}
            variant="secondary"
            size="md"
            withArrow
            className="after:absolute after:inset-0 after:content-['']"
          />
        </div>
      ) : null}
    </article>
  );
}
"use client";

import type { MouseEvent, ReactNode } from "react";

type HomeLinkProps = {
  "aria-label": string;
  className?: string;
  children: ReactNode;
};

/**
 * Link to the home page. Already on the home page, it glides back to the
 * top instead of reloading (and drops any #section from the URL); modified
 * clicks (new tab, etc.) and other pages keep normal link behaviour.
 * Reduced motion jumps instead of gliding.
 */
export function HomeLink({ children, ...props }: HomeLinkProps) {
  const onClick = (event: MouseEvent<HTMLAnchorElement>) => {
    const modified =
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey;
    if (modified || window.location.pathname !== "/") return;

    event.preventDefault();
    const reduce = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    window.scrollTo({ top: 0, behavior: reduce ? "auto" : "smooth" });
    if (window.location.hash) {
      window.history.replaceState(null, "", window.location.pathname);
    }
  };

  return (
    <a href="/" onClick={onClick} {...props}>
      {children}
    </a>
  );
}
import type { Preview } from "@storybook/nextjs-vite";
import { useEffect } from "react";
import { workSans } from "../src/app/fonts";
import "../src/app/globals.css";

const preview: Preview = {
  parameters: {
    // The two design boards plus the in-between widths we care about.
    viewport: {
      options: {
        narrow320: {
          name: "Narrowest supported (320)",
          styles: { width: "320px", height: "640px" },
        },
        board375: {
          name: "Mobile board (375)",
          styles: { width: "375px", height: "812px" },
        },
        tablet768: {
          name: "Tablet (768)",
          styles: { width: "768px", height: "1024px" },
        },
        board1440: {
          name: "Desktop board (1440)",
          styles: { width: "1440px", height: "900px" },
        },
      },
    },
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
  },
  decorators: [
    (Story) => {
      // Mirror the root layout: expose the Work Sans variable on <html>.
      useEffect(() => {
        document.documentElement.classList.add(
          workSans.variable,
          "antialiased",
        );
      }, []);
      return <Story />;
    },
  ],
};

export default preview;
import type { Metadata } from "next";
import { workSans } from "./fonts";
import "./globals.css";

export const metadata: Metadata = {
  title: "Apsu — Healthcare that speaks your language",
  description:
    "Care in the language you think in. US-licensed physicians, AI translates your consultation.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${workSans.variable} antialiased`}>
      <body>{children}</body>
    </html>
  );
}

