"use client";

import { useEffect, useRef, useState } from "react";
import type { TrustItem } from "@/content/schemas";
import { iconFor } from "@/features/shared/icon-map";
import { cn } from "@/lib/cn";
import { uiCopy } from "@/lib/ui-copy";

/** Scroll speed, px per second (about the board's original pace). */
const SPEED = 42;
/**
 * Copies per half on the server render: two sets already cover any width
 * up to ~2700px, so most screens never change after hydration.
 */
const DEFAULT_REPEATS = 2;

function Items({
  items,
  hidden,
  setRef,
}: {
  items: TrustItem[];
  hidden?: boolean;
  setRef?: (node: HTMLUListElement | null) => void;
}) {
  return (
    <ul
      ref={setRef}
      aria-hidden={hidden || undefined}
      className={cn(
        "flex shrink-0 items-center gap-strip-gap pr-strip-gap",
        // Reduced motion: one static, wrapping copy.
        hidden && "motion-reduce:hidden",
        "motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:pr-0",
      )}
    >
      {items.map((item) => {
        const Icon = iconFor(item.icon);
        return (
          <li
            key={item.id}
            className="flex items-center gap-2 whitespace-nowrap"
          >
            {Icon ? <Icon className="size-6 shrink-0" /> : null}
            {item.label}
          </li>
        );
      })}
    </ul>
  );
}

/**
 * Dark full-bleed band that scrolls left on its own (decision C2: CSS
 * marquee). The track is two identical halves and moves by -50%, which
 * loops seamlessly only if one half is at least as wide as the band; so
 * each half repeats the item set as often as the band's width needs
 * (measured, and re-measured on resize), and the duration follows the
 * half's length to keep the same speed everywhere. No gap ever opens at
 * the end and nothing pops in. Pauses on hover; static and wrapping under
 * reduced motion. Only the first set is exposed to assistive tech.
 */
export function TrustStrip({ items }: { items: TrustItem[] }) {
  const band = useRef<HTMLElement>(null);
  const set = useRef<HTMLUListElement | null>(null);
  const [layout, setLayout] = useState({
    repeats: DEFAULT_REPEATS,
    duration: 0,
  });

  useEffect(() => {
    const bandNode = band.current;
    const setNode = set.current;
    if (!bandNode || !setNode) return;
    const measure = () => {
      const setWidth = setNode.offsetWidth;
      if (setWidth === 0) return;
      const repeats = Math.max(
        DEFAULT_REPEATS,
        Math.ceil(bandNode.offsetWidth / setWidth),
      );
      setLayout({ repeats, duration: (repeats * setWidth) / SPEED });
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(bandNode);
    observer.observe(setNode); // web font swap changes the set width
    return () => observer.disconnect();
  }, []);

  if (items.length === 0) return null;
  const copies = layout.repeats * 2;
  return (
    <section
      ref={band}
      aria-label={uiCopy.trustStrip.label}
      className="mt-strip-top overflow-hidden bg-inverse py-5 text-strip text-white"
    >
      <div
        className="flex w-max animate-marquee hover:[animation-play-state:paused] motion-reduce:w-full motion-reduce:animate-none motion-reduce:px-gutter"
        style={
          layout.duration ? { animationDuration: `${layout.duration}s` } : {}
        }
      >
        {Array.from({ length: copies }, (_, copy) => (
          <Items
            // biome-ignore lint/suspicious/noArrayIndexKey: identical copies, the index is their identity
            key={copy}
            items={items}
            hidden={copy > 0}
            setRef={
              copy === 0
                ? (node) => {
                    set.current = node;
                  }
                : undefined
            }
          />
        ))}
      </div>
    </section>
  );
}
import { LogoIcon } from "@/components/icons";
import { SocialLinks } from "@/components/ui/social-links";
import { HomeLink } from "@/features/shared/HomeLink";
import { RichText } from "@/features/shared/RichText";
import { TextAction } from "@/features/shared/TextAction";
import { cn } from "@/lib/cn";
import { uiCopy } from "@/lib/ui-copy";
import type { SiteFooterProps } from "./to-footer-props";

type Props = SiteFooterProps & { className?: string };

const link =
  "text-left transition-colors duration-(--duration-fast) hover:text-mint-100 active:text-green-light";

/**
 * Dark footer: brand block and link columns, disclaimer, terms, a divider
 * aligned with the content edges (F13), socials and copyright, then the
 * giant wordmark cut off by the bottom of the page, fading into the
 * background.
 */
export function SiteFooter({
  tagline,
  columns,
  disclaimer,
  terms,
  socials,
  copyright,
  className,
}: Props) {
  return (
    <footer
      className={cn(
        "overflow-hidden bg-brand-900 px-footer-x pt-footer-top text-off-white",
        className,
      )}
    >
      <div className="mx-auto max-w-footer">
        <div className="flex flex-col gap-10 lg:flex-row lg:justify-between lg:gap-8">
          <div>
            <HomeLink aria-label={uiCopy.nav.home} className="inline-block">
              <LogoIcon className="h-20.75 w-56.5" />
            </HomeLink>
            <p className="mt-3 max-w-[22.5rem] text-footer-title">{tagline}</p>
          </div>

          <nav
            aria-label={uiCopy.footer.navLabel}
            className="grid gap-5 lg:grid-cols-[repeat(3,minmax(0,15.3125rem))] lg:gap-x-4 xl:gap-x-0"
          >
            {columns.map((column) => (
              <div key={column.id}>
                <h2 className="text-footer-title">{column.title}</h2>
                <ul className="mt-2.5 text-meta leading-7">
                  {column.items.map((item) => (
                    <li key={item.id}>
                      <TextAction link={item.link} className={link}>
                        {item.label}
                      </TextAction>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </div>

        <div className="mt-5 flex max-w-content flex-col gap-6 text-footer lg:mt-14 lg:gap-4">
          {disclaimer.map((paragraph) => (
            <p key={paragraph}>{paragraph}</p>
          ))}
          <p>
            <RichText segments={terms} linkClassName={link} />
          </p>
        </div>

        <div className="mt-8 flex flex-col gap-10 border-t border-border-footer pt-8 lg:mt-6 lg:flex-row lg:items-center lg:justify-between">
          <SocialLinks links={socials} tone="footer" />
          <p className="text-meta">{copyright}</p>
        </div>
      </div>

      {/* Giant wordmark: solid for the top ~40%, then fading out over a
          slightly lighter band; the page ends before its bottom (about 65%
          of it shows). Centred on the page, wider than the screen on mobile. */}
      <div
        aria-hidden
        className="-mx-footer-x mt-section-y bg-linear-to-b from-transparent from-35% via-brand-800 via-70% to-brand-900"
      >
        <div className="relative left-1/2 aspect-[4.215] w-wordmark -translate-x-1/2 overflow-hidden [mask-image:linear-gradient(to_bottom,black_39%,transparent)]">
          <LogoIcon className="absolute inset-x-0 top-0 aspect-[87/32] h-auto w-full" />
        </div>
      </div>
    </footer>
  );
}

