import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { faqs, homeContent } from "@/content/mock";
import { FaqSection } from "./FaqSection";
import { toFaqProps } from "./to-faq-props";

const props = toFaqProps(homeContent, faqs);
const ids = props.items.map((item) => item.id);

const meta = {
  title: "Sections/FAQ",
  component: FaqSection,
  args: props,
  parameters: { layout: "fullscreen" },
  globals: { viewport: { value: "board1440", isRotated: false } },
  decorators: [
    (Story) => (
      <div className="bg-page">
        <Story />
      </div>
    ),
  ],
} satisfies Meta<typeof FaqSection>;

export default meta;
type Story = StoryObj<typeof meta>;

/** As designed: the first question open. */
export const Default: Story = {};
export const Mobile: Story = {
  globals: { viewport: { value: "board375", isRotated: false } },
};
export const AllClosed: Story = { args: { defaultOpen: [] } };
/** Several answers open at once (multi-open accordion). */
export const SeveralOpen: Story = { args: { defaultOpen: ids } };

/** C7: an extreme answer length to check the open state copes. */
export const VeryLongAnswer: Story = {
  args: {
    defaultOpen: ["long"],
    items: [
      {
        id: "long",
        question:
          "A deliberately long question that wraps onto several lines on small screens to check the header layout?",
        answer: Array.from(
          { length: 6 },
          (_, index) =>
            `Paragraph ${index + 1}. Your physician reviews your history, explains each option in your language and adjusts the plan as you go; nothing ships until a licensed provider approves it, and your care team stays available for questions throughout treatment.`,
        ),
      },
      ...props.items.slice(1),
    ],
  },
};

/** Row states: closed hover, open hover, pressed, keyboard focus. */
export const ClosedHover: Story = {
  parameters: { pseudo: { hover: ['button[aria-expanded="false"]'] } },
};
export const OpenHover: Story = {
  parameters: { pseudo: { hover: ['button[aria-expanded="true"]'] } },
};
export const Pressed: Story = {
  parameters: { pseudo: { active: ['button[aria-expanded="false"]'] } },
};
export const Focus: Story = {
  parameters: { pseudo: { focusVisible: ['button[aria-expanded="false"]'] } },
};
import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { homeContent, services } from "@/content/mock";
import { ServiceCard } from "./ServiceCard";
import { ServicesCarousel } from "./ServicesCarousel";
import { toOnlineCareProps } from "./to-online-care-props";

const props = toOnlineCareProps(homeContent, services);

const meta = {
  title: "Sections/Services carousel",
  component: ServicesCarousel,
  args: props,
  parameters: { layout: "fullscreen" },
  globals: { viewport: { value: "board1440", isRotated: false } },
} satisfies Meta<typeof ServicesCarousel>;

export default meta;
type Story = StoryObj<typeof meta>;

/** At the start: "previous" is disabled; drag/swipe or use the arrows. */
export const Start: Story = {};

/** Scrolled to the last card: "next" is disabled. */
export const End: Story = { args: { defaultIndex: 3 } };

/** Middle: both arrows enabled. */
export const Middle: Story = { args: { defaultIndex: 1 } };

export const Mobile: Story = {
  globals: { viewport: { value: "board375", isRotated: false } },
};

/** Arrow states (same bubble states as every circular control). */
export const ArrowHover: Story = {
  args: { defaultIndex: 1 },
  parameters: { pseudo: { hover: ['button[aria-label="Next"]'] } },
};
export const ArrowPressed: Story = {
  args: { defaultIndex: 1 },
  parameters: { pseudo: { active: ['button[aria-label="Next"]'] } },
};
export const ArrowFocus: Story = {
  args: { defaultIndex: 1 },
  parameters: { pseudo: { focusVisible: ['button[aria-label="Next"]'] } },
};

const cardStory = (index: number): Story => ({
  render: () => {
    const service = props.services[index];
    return (
      <div className="flex justify-center bg-page p-10">
        {service ? <ServiceCard {...service} /> : null}
      </div>
    );
  },
});

/** Card layouts by media kind. */
export const CardChat = cardStory(0);
export const CardPhoto = cardStory(1);
export const CardProduct = cardStory(2);
import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { useState } from "react";
import { NumberField } from "./number-field";
import { RadioPill } from "./radio-pill";
import { SegmentedControl } from "./segmented-control";

/** Form controls used by the BMI calculator (one story per state). */
const meta = {
  title: "UI/Form controls",
  parameters: { layout: "centered" },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

// ---- SegmentedControl --------------------------------------------------
function Units({ initial = "imperial" }: { initial?: "imperial" | "metric" }) {
  const [value, setValue] = useState(initial);
  return (
    <SegmentedControl
      label="Units"
      value={value}
      onChange={setValue}
      options={[
        { value: "imperial", label: "ft / lbs" },
        { value: "metric", label: "cm / kg" },
      ]}
    />
  );
}

/** Click the other option: the pill slides with a liquid squash. */
export const SegmentedDefault: Story = { render: () => <Units /> };
export const SegmentedSecondSelected: Story = {
  render: () => <Units initial="metric" />,
};
export const SegmentedHover: Story = {
  render: () => <Units />,
  parameters: { pseudo: { hover: ["label:nth-of-type(2)"] } },
};
export const SegmentedFocus: Story = {
  render: () => <Units />,
  parameters: { pseudo: { focusVisible: ["input"] } },
};

// ---- NumberField -------------------------------------------------------
function Field(props: { initial?: string; error?: string }) {
  const [value, setValue] = useState(props.initial ?? "");
  return (
    <div className="w-60">
      <NumberField
        label="Height in feet"
        unit="ft"
        value={value}
        onChange={setValue}
        min={3}
        max={8}
        placeholder="0"
        error={props.error}
        incrementLabel="Increase feet"
        decrementLabel="Decrease feet"
      />
    </div>
  );
}

export const NumberEmpty: Story = { render: () => <Field /> };
export const NumberFilled: Story = { render: () => <Field initial="5" /> };
export const NumberHover: Story = {
  render: () => <Field initial="5" />,
  parameters: { pseudo: { hover: true } },
};
export const NumberFocus: Story = {
  render: () => <Field initial="5" />,
  parameters: { pseudo: { focusVisible: ["input"] } },
};
export const NumberInvalid: Story = {
  render: () => <Field initial="12" error="Enter 3–8 ft" />,
};

// ---- RadioPill ---------------------------------------------------------
function Sex({ initial = "female" }: { initial?: string }) {
  const [value, setValue] = useState(initial);
  return (
    <fieldset className="flex gap-3">
      <legend className="sr-only">Sex</legend>
      {["male", "female"].map((option) => (
        <RadioPill
          key={option}
          name="sex-story"
          value={option}
          checked={value === option}
          onChange={() => setValue(option)}
          className="w-32"
        >
          {option === "male" ? "Male" : "Female"}
        </RadioPill>
      ))}
    </fieldset>
  );
}

export const RadioDefault: Story = { render: () => <Sex /> };
export const RadioHover: Story = {
  render: () => <Sex />,
  parameters: { pseudo: { hover: ["label:first-of-type"] } },
};
export const RadioFocus: Story = {
  render: () => <Sex />,
  parameters: { pseudo: { focusVisible: ["input"] } },
};
export const RadioOtherChecked: Story = {
  render: () => <Sex initial="male" />,
};

