import type { Link } from "@/content/schemas";

/**
 * Turn a content Link into an href, or null when there is no destination
 * yet (`none`): such controls render as buttons with press feedback only.
 */
export function hrefFor(link: Link): string | null {
  switch (link.type) {
    case "anchor":
      return `#${link.target}`;
    case "route":
      return link.path;
    case "external":
      return link.url;
    case "none":
      return null;
  }
}
src/features/shared/nav-items.ts
import type { Link, NavItem, Program } from "@/content/schemas";

export type NavItemView = {
  id: string;
  label: string;
  link: Link;
  /** Section on this page the item scrolls to (for active highlighting). */
  sectionId: string | null;
};

/**
 * Resolve nav/footer items: program references take the program's name and
 * scroll to its section; references to missing programs are skipped.
 */
export function resolveNavItems(
  items: readonly NavItem[],
  programs: readonly Program[],
): NavItemView[] {
  return items.flatMap((item): NavItemView[] => {
    if (item.kind === "program") {
      const program = programs.find((p) => p.id === item.programId);
      if (!program) return [];
      return [
        {
          id: `program-${program.id}`,
          label: program.name,
          link: { type: "anchor", target: program.id },
          sectionId: program.id,
        },
      ];
    }
    return [
      {
        id: `link-${item.label}`,
        label: item.label,
        link: item.link,
        sectionId: item.link.type === "anchor" ? item.link.target : null,
      },
    ];
  });
}

