import type { Cta } from "@/content/schemas";
import { TextAction } from "@/features/shared/TextAction";
import { uiCopy } from "@/lib/ui-copy";
import { BmiGauge } from "./BmiGauge";
import { BmiScale } from "./BmiScale";
import {
  type BmiInput,
  calculateBmi,
  categorize,
  convertInput,
  type FieldName,
  LIMITS,
  type Sex,
  type UnitSystem,
  validate,
} from "./bmi";

export type BmiCalculatorProps = {
  eyebrow: string;
  tag: string;
  heading: string;
  helper: string;
  optionsCta: Cta | null;
  /** Prefill (stories, or a future profile); empty by default (C9). */
  defaultInput?: BmiInput;
  defaultSex?: Sex;
  /** Show the result for the prefilled values on first render. */
  defaultCalculated?: boolean;
};

const EMPTY: BmiInput = {
  unit: "imperial",
  heightFt: "",
  heightIn: "",
  heightCm: "",
  weight: "",
};

const copy = uiCopy.bmi;

/**
 * BMI / eligibility checker. Rules are pure functions in ./bmi (decision
 * 3.1); nothing is stored (3.2: refresh clears it). The button stays
 * disabled until the input is valid; out-of-range values show a message.
 * Switching units converts the typed values and recalculates an existing
 * result. The result names the chosen sex (C6) — the number itself does
 * not depend on it.
 *
 * Mobile follows the mobile board (one card, gauge on top, no legend/link);
 * from lg it is the form card + result card of the desktop board.
 */
export function BmiCalculator({
  eyebrow,
  tag,
  heading,
  helper,
  optionsCta,
  defaultInput = EMPTY,
  defaultSex = "female",
  defaultCalculated = false,
}: BmiCalculatorProps) {
  const headingId = useId();
  const [input, setInput] = useState<BmiInput>(defaultInput);
  const [sex, setSex] = useState<Sex>(defaultSex);
  const [bmi, setBmi] = useState<number | null>(() =>
    defaultCalculated ? calculateBmi(defaultInput) : null,
  );

  const errors = validate(input);
  const valid = Object.keys(errors).length === 0;
  const imperial = input.unit === "imperial";

  const set = (field: FieldName) => (value: string) =>
    setInput((current) => ({ ...current, [field]: value }));

  const changeUnit = (unit: UnitSystem) => {
    const next = convertInput(input, unit);
    setInput(next);
    if (bmi !== null) setBmi(calculateBmi(next));
  };

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (valid) setBmi(calculateBmi(input));
  };

  // Only out-of-range values get a message; empty fields just keep the
  // button disabled.
  const rangeError = (
    field: FieldName,
    min: number,
    max: number,
    unit: string,
  ) => (errors[field] === "range" ? copy.range(min, max, unit) : undefined);

  const resultText =
    bmi === null
      ? copy.empty
      : copy.result(sex, bmi.toFixed(1), copy.categories[categorize(bmi)]);

  const field = (
    name: FieldName,
    label: string,
    unit: string,
    [min, max]: readonly [number, number],
  ) => (
    <NumberField
      label={label}
      unit={unit}
      value={input[name]}
      onChange={set(name)}
      min={min}
      max={max}
      placeholder="0"
      error={rangeError(name, min, max, unit)}
      incrementLabel={copy.increase(label)}
      decrementLabel={copy.decrease(label)}
    />
  );

  return (
    <div className="mx-auto mt-8 max-w-content rounded-shell lg:bg-surface lg:p-3">
      <div className="relative isolate overflow-hidden rounded-card p-3 shadow-card lg:p-10">
        <Image
          src="/images/bmi-background.webp"
          alt=""
          fill
          sizes="(min-width: 80rem) 81rem, 100vw"
          className="-z-10 object-cover"
        />
        <div
          aria-hidden
          className="absolute inset-0 -z-10 bg-[rgb(60_58_58/0.6)]"
        />

        <div className="mx-auto grid max-w-[73rem] gap-6 lg:grid-cols-[34.6875rem_minmax(0,1fr)] lg:items-end">
          <form
            aria-labelledby={headingId}
            noValidate
            onSubmit={onSubmit}
            className="flex flex-col gap-6 rounded-card border border-mint-100 bg-surface p-3 shadow-soft lg:p-6"
          >
            <div className="flex items-start justify-between gap-4">
              <div className="flex flex-col gap-3">
                <Eyebrow className="hidden lg:block">{eyebrow}</Eyebrow>
                <div className="flex flex-col gap-2 lg:gap-4">
                  <h3
                    id={headingId}
                    className="max-w-[19.5rem] text-title font-medium text-heading-strong"
                  >
                    {heading}
                  </h3>
                  <p className="text-body-sm text-copy">{helper}</p>
                </div>
              </div>
              <Eyebrow className="hidden lg:block">{tag}</Eyebrow>
            </div>

            {/* Mobile board: the gauge sits inside the form card. */}
            <div className="flex flex-col items-center gap-2 lg:hidden">
              <BmiGauge
                bmi={bmi}
                label={copy.scoreLabelShort}
                className="w-34"
              />
            </div>

            <div className="flex flex-col gap-4">
              <SegmentedControl
                label={copy.units.label}
                value={input.unit}
                onChange={changeUnit}
                options={[
                  { value: "imperial", label: copy.units.imperial },
                  { value: "metric", label: copy.units.metric },
                ]}
                className="w-45"
              />

              <div className="grid gap-4 lg:grid-cols-[auto_minmax(0,1fr)] lg:gap-3">
                <div className="flex flex-col gap-2">
                  <span className="text-label text-copy">{copy.height}</span>
                  {imperial ? (
                    <div className="grid grid-cols-2 gap-3 lg:w-[16.125rem]">
                      {field(
                        "heightFt",
                        copy.fieldLabels.heightFt,
                        copy.unitSuffix.ft,
                        LIMITS.imperial.heightFt,
                      )}
                      {field(
                        "heightIn",
                        copy.fieldLabels.heightIn,
                        copy.unitSuffix.in,
                        LIMITS.imperial.heightIn,
                      )}
                    </div>
                  ) : (
                    <div className="lg:w-[16.125rem]">
                      {field(
                        "heightCm",
                        copy.fieldLabels.heightCm,
                        copy.unitSuffix.cm,
                        LIMITS.metric.heightCm,
                      )}
                    </div>
                  )}
                </div>
                <div className="flex flex-col gap-2">
                  <span className="text-label text-copy">{copy.weight}</span>
                  {imperial
                    ? field(
                        "weight",
                        copy.fieldLabels.weightLb,
                        copy.unitSuffix.lbs,
                        LIMITS.imperial.weightLb,
                      )
                    : field(
                        "weight",
                        copy.fieldLabels.weightKg,
                        copy.unitSuffix.kg,
                        LIMITS.metric.weightKg,
                      )}
                </div>
              </div>

              <fieldset className="m-0 min-w-0 border-0 p-0">
                <legend className="mb-2 text-label text-copy">
                  {copy.sex}
                </legend>
                <div className="grid grid-cols-2 gap-3 lg:flex">
                  {(["male", "female"] as const).map((option) => (
                    <RadioPill
                      key={option}
                      name={`${headingId}-sex`}
                      value={option}
                      checked={sex === option}
                      onChange={() => setSex(option)}
                      className="lg:w-[7.6875rem]"
                    >
                      {copy.sexes[option]}
                    </RadioPill>
                  ))}
                </div>
              </fieldset>
            </div>

            <Button
              type="submit"
              size="lg"
              fullWidth
              disabled={!valid}
              className="justify-center font-normal"
            >
              {copy.submit}
            </Button>

            {/* Mobile: the result sentence under the button. */}
            <p
              aria-live="polite"
              className="text-center text-body-sm text-copy lg:hidden"
            >
              {resultText}
            </p>
          </form>

          <section
            aria-label={copy.scoreLabel}
            className="hidden flex-col items-center gap-6 rounded-card border border-[rgb(12_27_46/0.08)] bg-surface px-6 py-8 shadow-soft lg:flex"
          >
            <BmiGauge bmi={bmi} label={copy.scoreLabel} className="w-54" />
            <p
              aria-live="polite"
              className="text-center text-body-sm text-copy"
            >
              {resultText}
            </p>
            <BmiScale bmi={bmi} />
            {optionsCta ? (
              <TextAction
                link={optionsCta.link}
                className="group/link inline-flex items-center gap-2 self-start rounded-full text-label text-heading transition-colors hover:text-accent"
              >
                {optionsCta.label}
                <ArrowRightCircleIcon className="size-6 transition-transform duration-(--duration-base) group-hover/link:translate-x-0.5" />
              </TextAction>
            ) : null}
          </section>
        </div>
      </div>
    </div>
  );
}
src/features/bmi/bmi.ts
/**
 * BMI rules (decision 3.1: fixed in the front end). Pure functions only, so
 * they are unit-tested and could later be swapped for an API call without
 * touching the component.
 *
 * Adult BMI = kg / m². Categories (WHO adult ranges) are the same for women
 * and men; the sex field does not change the number (decision C6, K21).
 */

export type UnitSystem = "imperial" | "metric";
export type Sex = "male" | "female";

export type BmiCategory = "underweight" | "healthy" | "overweight" | "obese";

/** Lower bounds of each category, in order. */
export const BMI_THRESHOLDS: readonly { category: BmiCategory; min: number }[] =
  [
    { category: "underweight", min: 0 },
    { category: "healthy", min: 18.5 },
    { category: "overweight", min: 25 },
    { category: "obese", min: 30 },
  ];

const CM_PER_INCH = 2.54;
const KG_PER_LB = 0.45359237;

/** Accepted input ranges (plausible adult values). */
export const LIMITS = {
  metric: { heightCm: [90, 250], weightKg: [20, 320] },
  imperial: { heightFt: [3, 8], heightIn: [0, 11], weightLb: [45, 700] },
} as const;

export type BmiInput = {
  unit: UnitSystem;
  /** Raw field values (strings, as typed). */
  heightFt: string;
  heightIn: string;
  heightCm: string;
  weight: string;
};

export type FieldName = "heightFt" | "heightIn" | "heightCm" | "weight";
export type FieldError = "required" | "range";

const parse = (value: string): number | null => {
  if (value.trim() === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const inRange = (n: number, [min, max]: readonly [number, number]) =>
  n >= min && n <= max;

/** Per-field validation for the current unit system. */
export function validate(
  input: BmiInput,
): Partial<Record<FieldName, FieldError>> {
  const errors: Partial<Record<FieldName, FieldError>> = {};
  const check = (
    field: FieldName,
    range: readonly [number, number],
    required = true,
  ) => {
    const n = parse(input[field]);
    if (n === null) {
      if (required) errors[field] = "required";
    } else if (!inRange(n, range)) {
      errors[field] = "range";
    }
  };
  if (input.unit === "metric") {
    check("heightCm", LIMITS.metric.heightCm);
    check("weight", LIMITS.metric.weightKg);
  } else {
    check("heightFt", LIMITS.imperial.heightFt);
    // Inches may be left empty (= 0).
    check("heightIn", LIMITS.imperial.heightIn, false);
    check("weight", LIMITS.imperial.weightLb);
  }
  return errors;
}

/** Height in cm and weight in kg, or null when the input is not valid. */
export function toMetric(input: BmiInput): { cm: number; kg: number } | null {
  if (Object.keys(validate(input)).length > 0) return null;
  if (input.unit === "metric") {
    return { cm: Number(input.heightCm), kg: Number(input.weight) };
  }
  const inches = Number(input.heightFt) * 12 + (parse(input.heightIn) ?? 0);
  return { cm: inches * CM_PER_INCH, kg: Number(input.weight) * KG_PER_LB };
}

export function bmiFromMetric(cm: number, kg: number): number {
  const m = cm / 100;
  return kg / (m * m);
}

/** BMI rounded to one decimal, or null for invalid input. */
export function calculateBmi(input: BmiInput): number | null {
  const metric = toMetric(input);
  if (!metric) return null;
  return Math.round(bmiFromMetric(metric.cm, metric.kg) * 10) / 10;
}

export function categorize(bmi: number): BmiCategory {
  let result: BmiCategory = "underweight";
  for (const { category, min } of BMI_THRESHOLDS)
    if (bmi >= min) result = category;
  return result;
}

/**
 * Convert the typed values when the unit system changes (decision: keep
 * the user's numbers instead of clearing them). Empty fields stay empty.
 */
export function convertInput(input: BmiInput, to: UnitSystem): BmiInput {
  if (input.unit === to) return input;
  const height = parse(
    input.unit === "metric" ? input.heightCm : input.heightFt,
  );
  const weight = parse(input.weight);

  if (to === "metric") {
    const inches =
      height === null ? null : height * 12 + (parse(input.heightIn) ?? 0);
    return {
      unit: "metric",
      heightFt: "",
      heightIn: "",
      heightCm: inches === null ? "" : String(Math.round(inches * CM_PER_INCH)),
      weight: weight === null ? "" : String(Math.round(weight * KG_PER_LB)),
    };
  }

  let ft = "";
  let inch = "";
  if (height !== null) {
    const totalIn = Math.round(height / CM_PER_INCH);
    ft = String(Math.floor(totalIn / 12));
    inch = String(totalIn % 12);
  }
  return {
    unit: "imperial",
    heightFt: ft,
    heightIn: inch,
    heightCm: "",
    weight: weight === null ? "" : String(Math.round(weight / KG_PER_LB)),
  };
}

/**
 * Position (0–1) of a BMI on the scale bar. The four labels sit in equal
 * quarters, so each category maps onto its quarter.
 */
export function scalePosition(bmi: number): number {
  const segments: [number, number][] = [
    [12, 18.5],
    [18.5, 25],
    [25, 30],
    [30, 40],
  ];
  for (let i = 0; i < segments.length; i++) {
    const [lo, hi] = segments[i] ?? [0, 1];
    if (bmi < hi || i === segments.length - 1) {
      const t = Math.min(1, Math.max(0, (bmi - lo) / (hi - lo)));
      return (i + t) / segments.length;
    }
  }
  return 1;
}

/** Fraction (0–1) of the gauge ring to fill: BMI 12 -> 0, BMI 40 -> 1. */
export function gaugeFraction(bmi: number): number {
  return Math.min(1, Math.max(0, (bmi - 12) / (40 - 12)));
}
src/components/ui/number-field/NumberField.tsx
import { type ChangeEvent, type InputHTMLAttributes, useId } from "react";
import { SortIcon } from "@/components/icons";
import { cn } from "@/lib/cn";

type NumberFieldProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "type" | "value" | "onChange"
> & {
  /** Accessible name (the visible label may be shared by several fields). */
  label: string;
  value: string;
  onChange: (value: string) => void;
  /** Unit shown inside the field ("ft", "in", "lbs", "cm", "kg"). */
  unit: string;
  step?: number;
  min?: number;
  max?: number;
  /** Error message; marks the field invalid and is announced. */
  error?: string;
  /** Accessible names for the stepper buttons. */
  incrementLabel: string;
  decrementLabel: string;
};

/**
 * Pill number input with a unit suffix and the design's up/down stepper
 * (the sort icon split into two hit areas). Arrow keys step natively.
 * Self-designed states: hover = darker border, focus = ring, invalid = red
 * border + message.
 */
export function NumberField({
  label,
  value,
  onChange,
  unit,
  step = 1,
  min,
  max,
  error,
  incrementLabel,
  decrementLabel,
  className,
  id,
  ...props
}: NumberFieldProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const errorId = `${inputId}-error`;

  const stepBy = (direction: 1 | -1) => {
    // Empty field: either button starts from the minimum.
    if (value.trim() === "") {
      onChange(String(min ?? 0));
      return;
    }
    const current = Number(value);
    if (!Number.isFinite(current)) return;
    let next = current + direction * step;
    if (min !== undefined) next = Math.max(min, next);
    if (max !== undefined) next = Math.min(max, next);
    onChange(String(Math.round(next * 100) / 100));
  };

  return (
    <div className={cn("flex flex-col gap-1", className)}>
      <div
        className={cn(
          "flex h-control items-center gap-1 rounded-full border bg-input pr-3 pl-4",
          "transition-[border-color,box-shadow] duration-(--duration-fast)",
          "has-[input:focus-visible]:outline-2 has-[input:focus-visible]:outline-offset-2 has-[input:focus-visible]:outline-focus",
          error ? "border-danger" : "border-border hover:border-sage-300",
        )}
      >
        <input
          id={inputId}
          type="number"
          inputMode="decimal"
          aria-label={label}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? errorId : undefined}
          value={value}
          min={min}
          max={max}
          step={step}
          onChange={(event: ChangeEvent<HTMLInputElement>) =>
            onChange(event.target.value)
          }
          className={cn(
            "w-full min-w-0 bg-transparent text-button text-heading-strong outline-none placeholder:text-ink-400",
            "[appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none",
          )}
          {...props}
        />
        <span className="relative flex shrink-0 flex-col text-sage-400">
          <SortIcon className="size-6" />
          <button
            type="button"
            tabIndex={-1}
            aria-label={incrementLabel}
            onClick={() => stepBy(1)}
            className="absolute inset-x-0 top-0 h-1/2 cursor-pointer rounded-t-full hover:bg-sage-200/40 active:bg-sage-200/70"
          />
          <button
            type="button"
            tabIndex={-1}
            aria-label={decrementLabel}
            onClick={() => stepBy(-1)}
            className="absolute inset-x-0 bottom-0 h-1/2 cursor-pointer rounded-b-full hover:bg-sage-200/40 active:bg-sage-200/70"
          />
        </span>
        <span aria-hidden className="shrink-0 text-button text-ink-500">
          {unit}
        </span>
      </div>
      {error ? (
        <p id={errorId} className="px-4 text-caption leading-snug text-danger">
          {error}
        </p>
      ) : null}
    </div>
  );
}
src/components/ui/radio-pill/RadioPill.tsx
import type { InputHTMLAttributes, ReactNode } from "react";
import { RadioCheckedIcon, RadioUncheckedIcon } from "@/components/icons";
import { cn } from "@/lib/cn";

type RadioPillProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type"> & {
  children: ReactNode;
};

/**
 * Pill-shaped radio option (BMI "Sex"). A native radio keeps group
 * semantics and keyboard behaviour; the design's radio icons show the state.
 * Self-designed states: hover = darker border + tint, pressed = small
 * shrink, focus = ring on the pill, checked = filled icon + dark border.
 */
export function RadioPill({
  children,
  checked,
  className,
  ...props
}: RadioPillProps) {
  return (
    <label
      className={cn(
        "flex h-control min-w-0 cursor-pointer items-center gap-1 rounded-full border px-4",
        "text-button text-heading-strong transition-[border-color,background-color,scale] duration-(--duration-base) ease-standard",
        "hover:bg-faq-tint active:scale-[0.97]",
        "has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-focus",
        checked ? "border-primary" : "border-border hover:border-sage-300",
        className,
      )}
    >
      <input type="radio" checked={checked} className="sr-only" {...props} />
      {checked ? (
        <RadioCheckedIcon className="size-6 shrink-0 text-primary" />
      ) : (
        <RadioUncheckedIcon className="size-6 shrink-0 text-sage-200" />
      )}
      {children}
    </label>
  );
}

