                      value={option}
                      checked={sex === option}
                      onChange={() => setSex(option)}
                      className="lg:w-[7.6875rem]"
                    >
                      {copy.sexes[option]}
                    </RadioPill>
                  ))}
                </div>
              </fieldset>
            </div>

            <Button
              type="submit"
              size="lg"
              fullWidth
              disabled={!valid}
              className="justify-center font-normal"
            >
              {copy.submit}
            </Button>

            {/* Mobile: the result sentence under the button. */}
            <p
              aria-live="polite"
              className="text-center text-body-sm text-copy lg:hidden"
            >
              {resultText}
            </p>
