          items={rows[1] ?? []}
          direction={1}
          start={ROW_STARTS[1]?.desktop ?? FALLBACK_START}
          startMobile={ROW_STARTS[1]?.mobile ?? FALLBACK_START}
          zone={zone}
          reduce={reduce}
          selected={selected}
          onToggle={toggle}
        />
