import type {
  Cta,
  HighlightCard,
  HomeContent,
  Image,
  Product,
  Program,
  RecurringPrice,
  RichText,
} from "@/content/schemas";

export type ProductCardProps = {
  id: string;
  name: string;
  price: RecurringPrice;
  image: Image;
  cta: Cta | null;
};

/** Desktop layout of a feature card (measured on the 1440 board). */
export type SectionLayout = {
  /** Min height of the card from lg, rem (the photo scales with it). */
  minHeight: number;
  /** Max width of the copy column (heading, intro, price divider), rem. */
  copyWidth: number;
  /** Horizontal centre of the photo, % of the card width. */
  imageCenterX: number;
  /** Photo height, % of the card height (>100 rises above the card). */
  imageHeight: number;
  /**
   * Max photo width, % of the card width: its share at 1440. Narrower cards
   * (1024-1440) shrink the photo in place instead of letting it run into
   * the copy column.
   */
  imageMaxWidth: number;
};

export type ProgramSectionProps = {
  id: string;
  /** Program category -> theme (unknown -> default). */
  category: string;
  imageSide: "left" | "right";
  layout: SectionLayout;
  /** Program name shown as the eyebrow (only when the content asks for it). */
  eyebrow: string | null;
  heading: RichText;
  intro: string[];
  points: string[];
  startingPrice: RecurringPrice | null;
  cta: Cta;
  image: Image;
  highlights: HighlightCard[];
  products: ProductCardProps[];
};

/**
 * Layout per category is presentation, so it lives here, not in the data.
 * Values measured on the 1440 board: the sleep photo sits on the left, and
 * each card has its own copy width and photo height / position.
 */
const imageSideByCategory: Record<string, "left" | "right"> = {
  sleep: "left",
};

const layoutByCategory: Record<string, SectionLayout> = {
  "weight-loss": {
    minHeight: 38.6875,
    copyWidth: 28.5,
    imageCenterX: 70.7,
    imageHeight: 111.8,
    imageMaxWidth: 46.8,
  },
  "birth-control": {
    minHeight: 44.875,
    copyWidth: 38.5,
    imageCenterX: 79.5,
    imageHeight: 104.6,
    imageMaxWidth: 30.7,
  },
  sleep: {
    minHeight: 44.875,
    copyWidth: 34.4375,
    imageCenterX: 23.9,
    imageHeight: 104.7,
    imageMaxWidth: 44.6,
  },
};
const defaultLayout: SectionLayout = {
  minHeight: 42,
  copyWidth: 34.5,
  imageCenterX: 72,
  imageHeight: 105,
  imageMaxWidth: 45,
};

/** API content -> program sections (in the order home content lists them). */
export function toProgramSectionsProps(
  home: HomeContent,
  programs: readonly Program[],
  products: readonly Product[],
): ProgramSectionProps[] {
  const productCta = home.ctas[home.programs.productCtaRef] ?? null;

  return home.programs.programIds.flatMap((id) => {
    const program = programs.find((p) => p.id === id);
    if (!program) return [];
    const { section } = program;
    return [
      {
        id: program.id,
        category: program.category,
        imageSide: imageSideByCategory[program.category] ?? "right",
        layout: layoutByCategory[program.category] ?? defaultLayout,
        eyebrow: section.showEyebrow ? program.name : null,
        heading: section.heading,
        intro: section.intro,
        points: section.points,
        startingPrice: section.startingPrice ?? null,
        cta: section.cta,
        image: section.image,
        highlights: section.highlights ?? [],
        products: products
          .filter((product) => product.programId === program.id)
          .map((product) => ({
            id: product.id,
            name: product.name,
            price: product.price,
            image: product.image,
            cta: productCta,
          })),
      },
    ];
  });
}
import type {
  Cta,
  HomeContent,
  Image,
  Language,
  Program,
  RichText,
  TrustItem,
} from "@/content/schemas";

export type CategoryCardProps = {
  id: string;
  /** Program category -> front-end theme (unknown -> default). */
  category: string;
  eyebrow: string;
  title: string;
  image: Image;
  cta: Cta | null;
};

export type HeroProps = {
  badges: TrustItem[];
  headline: RichText;
  subtitle: string[];
  cta: Cta | null;
  languages: Language[];
  highlightedLanguages: string[];
  categories: CategoryCardProps[];
};

/** API content -> hero props. Category cards come from the programs. */
export function toHeroProps(
  home: HomeContent,
  programs: readonly Program[],
  languages: readonly Language[],
): HeroProps {
  const { hero } = home;
  const categoryCta = home.ctas[hero.categories.ctaRef] ?? null;

  return {
    badges: hero.badges,
    headline: hero.headline,
    subtitle: hero.subtitle,
    cta: home.ctas[hero.ctaRef] ?? null,
    languages: [...languages],
    highlightedLanguages: hero.highlightedLanguages,
    categories: hero.categories.programIds.flatMap((id) => {
      const program = programs.find((p) => p.id === id);
      if (!program) return [];
      return [
        {
          id: program.id,
          category: program.category,
          eyebrow: program.card.eyebrow,
          title: program.card.title,
          image: program.card.image,
          cta: categoryCta,
        },
      ];
    }),
  };
}
import type { SocialLink } from "@/components/ui/social-links";
import { pickByIds } from "@/content/api/pick-by-ids";
import type {
  HomeContent,
  Image,
  Program,
  RichText,
  SocialProfile,
  Testimonial,
} from "@/content/schemas";
import { uiCopy } from "@/lib/ui-copy";

export type StoryAuthor = {
  name: string;
  location: string;
  socials: SocialLink[];
};

export type StoryCardProps =
  | {
      kind: "quote";
      id: string;
      /** Program name, e.g. "Weight Loss" (null if the program is gone). */
      category: string | null;
      rating: number;
      quote: string;
      author: StoryAuthor;
    }
  | { kind: "photo"; id: string; photo: Image; author: StoryAuthor };

export type StoriesProps = {
  heading: RichText;
  subtitle: string | null;
  stories: StoryCardProps[];
};

const toSocialLinks = (
  name: string,
  socials: readonly SocialProfile[],
): SocialLink[] =>
  socials.map(({ platform, url }) => ({
    platform,
    href: url,
    label: uiCopy.social.profile(name, uiCopy.social.platforms[platform]),
  }));

/** API content -> "Our Success Stories" (order from home content). */
export function toStoriesProps(
  home: HomeContent,
  testimonials: readonly Testimonial[],
  programs: readonly Program[],
): StoriesProps {
  const { heading, subtitle, testimonialIds } = home.stories;
  return {
    heading,
    subtitle: subtitle ?? null,
    stories: pickByIds(testimonialIds, testimonials).map((item) => {
      const author: StoryAuthor = {
        name: item.author.name,
        location: item.author.location,
        socials: toSocialLinks(item.author.name, item.author.socials),
      };
      return item.kind === "quote"
        ? {
            kind: "quote",
            id: item.id,
            category:
              programs.find((program) => program.id === item.programId)?.name ??
              null,
            rating: item.rating,
            quote: item.quote,
            author,
          }
        : { kind: "photo", id: item.id, photo: item.photo, author };
    }),
  };
}
import type { SocialLink } from "@/components/ui/social-links";
import type { Cta, HomeContent, Program, RichText } from "@/content/schemas";
import { type NavItemView, resolveNavItems } from "@/features/shared/nav-items";
import { uiCopy } from "@/lib/ui-copy";

export type ClosingCtaProps = {
  heading: RichText;
  points: string[];
  cta: Cta | null;
};

export type FooterColumnView = {
  id: string;
  title: string;
  items: NavItemView[];
};

export type SiteFooterProps = {
  tagline: string;
  columns: FooterColumnView[];
  disclaimer: string[];
  terms: RichText;
  socials: SocialLink[];
  copyright: string;
};

/** API content -> closing call to action (the CTA label lives in home.ctas). */
export function toClosingCtaProps(home: HomeContent): ClosingCtaProps {
  const { heading, points, ctaRef } = home.closingCta;
  return { heading, points, cta: home.ctas[ctaRef] ?? null };
}

/** API content -> footer. Program links take the program's name. */
export function toFooterProps(
  home: HomeContent,
  programs: readonly Program[],
  year: number,
): SiteFooterProps {
  const { footer } = home;
  return {
    tagline: footer.tagline,
    columns: footer.columns.map((column) => ({
      id: column.id,
      title: column.title,
