    lastX: number;
    lastT: number;
    velocity: number;
    moved: number;
  } | null>(null);
  const suppressClick = useRef(false);

  // Measure one set (+ gap) and render enough copies to cover the row.
  useEffect(() => {
    const viewport = viewportRef.current;
    const set = setRef.current;
    const track = trackRef.current;
