        "motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:pr-0",
      )}
    >
      {items.map((item) => {
        const Icon = iconFor(item.icon);
        return (
          <li
            key={item.id}
            className="flex items-center gap-2 whitespace-nowrap"
          >
            {Icon ? <Icon className="size-6 shrink-0" /> : null}
            {item.label}
          </li>
        );
      })}
    </ul>
  );
