        {Array.from({ length: copies }, (_, copy) => (
          <Items
            // biome-ignore lint/suspicious/noArrayIndexKey: identical copies, the index is their identity
            key={copy}
            items={items}
            hidden={copy > 0}
            setRef={
              copy === 0
                ? (node) => {
                    set.current = node;
                  }
                : undefined
            }
          />
        ))}
      </div>
    </section>
  );
