    );
  }
  const external = link.type === "external";
  return (
    <a
      href={href}
      className={cn(className)}
      onClick={onClick}
      {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
      {...aria}
    >
      {children}
    </a>
  );
}
import { cva, type VariantProps } from "class-variance-authority";
