/**
 * Text link for nav, footer and inline copy. Without a destination it is a
 * button (press feedback only) so it stays keyboard accessible.
 */
export function TextAction({
  link,
  children,
  className,
  onClick,
  ...aria
}: TextActionProps) {
  const href = hrefFor(link);
