    defaultInput: {
      unit: "metric",
      heightFt: "",
      heightIn: "",
      heightCm: "180",
      weight: "90",
    },
    defaultCalculated: true,
  },
};

/** Mobile board: one card, gauge on top, result sentence under the button. */
export const MobileInitial: Story = {
  globals: { viewport: { value: "board375", isRotated: false } },
};
export const MobileResult: Story = {
  ...ResultHealthyWoman,
  globals: { viewport: { value: "board375", isRotated: false } },
};

