describe("RadioPill", () => {
  it("behaves as a native radio", async () => {
    const user = userEvent.setup();
    function Sex() {
      const [value, setValue] = useState("female");
      return (
        <fieldset>
          <legend>Sex</legend>
          {["male", "female"].map((option) => (
