import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it } from "vitest";
import { homeContent } from "@/content/mock";
import { BmiCalculator } from "./BmiCalculator";
import { toBmiProps } from "./to-bmi-props";

const { programId, ...props } = toBmiProps(homeContent);

describe("toBmiProps", () => {
  it("reads the host program and copy from content", () => {
    expect(programId).toBe("weight-loss");
    expect(props.heading).toBe("Could a GLP-1 program be right for you?");
  });
});

describe("BmiCalculator", () => {
  it("enables Calculate only for valid input and shows the C6 sentence", async () => {
    const user = userEvent.setup();
    render(<BmiCalculator {...props} />);
    const form = screen.getByRole("form", { name: props.heading });
    const submit = within(form).getByRole("button", { name: "Calculate BMI" });
    expect(submit).toBeDisabled();

    await user.type(
      within(form).getByRole("spinbutton", { name: "Height, feet" }),
      "5",
    );
    await user.type(
      within(form).getByRole("spinbutton", { name: "Height, inches" }),
      "7",
    );
    await user.type(
      within(form).getByRole("spinbutton", { name: "Weight, pounds" }),
      "150",
    );
    expect(submit).toBeEnabled();
    await user.click(submit);

    expect(
      screen.getAllByText("As a woman, your BMI is 23.5 — Healthy Weight.")
        .length,
    ).toBeGreaterThan(0);
  });

  it("converts typed values when switching units", async () => {
    const user = userEvent.setup();
    render(
      <BmiCalculator
        {...props}
        defaultInput={{
          unit: "imperial",
          heightFt: "6",
          heightIn: "0",
          heightCm: "",
          weight: "176",
        }}
      />,
    );
    await user.click(screen.getByText("cm / kg"));
    expect(
      screen.getByRole("spinbutton", { name: "Height, centimetres" }),
    ).toHaveValue(183);
    expect(
      screen.getByRole("spinbutton", { name: "Weight, kilograms" }),
    ).toHaveValue(80);
  });

  it("labels the legend from the thresholds (F08)", () => {
    render(<BmiCalculator {...props} />);
    expect(screen.getByText("18.5–24.9")).toBeInTheDocument();
    expect(screen.getByText("25–29.9")).toBeInTheDocument();
  });
});
import { describe, expect, it } from "vitest";
import {
  type BmiInput,
  calculateBmi,
  categorize,
  convertInput,
  gaugeFraction,
  scalePosition,
  validate,
} from "./bmi";

const imperial = (ft: string, inch: string, lb: string): BmiInput => ({
  unit: "imperial",
  heightFt: ft,
  heightIn: inch,
  heightCm: "",
  weight: lb,
});
const metric = (cm: string, kg: string): BmiInput => ({
  unit: "metric",
  heightFt: "",
  heightIn: "",
  heightCm: cm,
  weight: kg,
});

describe("calculateBmi", () => {
  it("computes metric BMI to one decimal", () => {
    expect(calculateBmi(metric("170", "70"))).toBe(24.2);
  });

  it("computes imperial BMI via inches", () => {
    // 5 ft 7 in, 150 lb -> 23.5
    expect(calculateBmi(imperial("5", "7", "150"))).toBe(23.5);
  });

  it("treats empty inches as zero", () => {
    expect(calculateBmi(imperial("6", "", "180"))).toBe(24.4);
  });

  it("returns null for invalid input", () => {
    expect(calculateBmi(metric("", "70"))).toBeNull();
    expect(calculateBmi(metric("40", "70"))).toBeNull();
  });
});

describe("categorize", () => {
  it.each([
    [18.4, "underweight"],
    [18.5, "healthy"],
    [24.9, "healthy"],
    [25, "overweight"],
    [29.9, "overweight"],
    [30, "obese"],
  ] as const)("BMI %s is %s", (bmi, category) => {
    expect(categorize(bmi)).toBe(category);
  });
});

describe("validate", () => {
  it("requires height and weight but not inches", () => {
    expect(validate(imperial("", "", ""))).toEqual({
      heightFt: "required",
      weight: "required",
    });
    expect(validate(imperial("5", "", "150"))).toEqual({});
  });

  it("flags out-of-range and non-numeric values", () => {
    expect(validate(imperial("5", "12", "150")).heightIn).toBe("range");
    expect(validate(metric("170", "5")).weight).toBe("range");
    expect(validate(metric("abc", "70")).heightCm).toBe("required");
  });
});

describe("convertInput", () => {
  it("converts imperial to metric", () => {
    expect(convertInput(imperial("5", "7", "150"), "metric")).toMatchObject({
      unit: "metric",
      heightCm: "170",
      weight: "68",
    });
  });

  it("converts metric to imperial with inches below 12", () => {
    expect(convertInput(metric("183", "80"), "imperial")).toMatchObject({
      unit: "imperial",
      heightFt: "6",
      heightIn: "0",
      weight: "176",
    });
  });

  it("keeps empty fields empty", () => {
    expect(convertInput(imperial("", "", "150"), "metric")).toMatchObject({
      heightCm: "",
      weight: "68",
    });
  });

  it("round-trips to a similar BMI", () => {
    const start = imperial("5", "7", "150");
    const there = convertInput(start, "metric");
    expect(
      Math.abs((calculateBmi(there) ?? 0) - (calculateBmi(start) ?? 0)),
    ).toBeLessThan(0.3);
  });
});

describe("scale and gauge positions", () => {
  it("puts category boundaries on the quarter marks", () => {
    expect(scalePosition(18.5)).toBeCloseTo(0.25);
    expect(scalePosition(25)).toBeCloseTo(0.5);
    expect(scalePosition(30)).toBeCloseTo(0.75);
  });

  it("clamps extremes", () => {
    expect(scalePosition(5)).toBe(0);
    expect(scalePosition(80)).toBe(1);
    expect(gaugeFraction(5)).toBe(0);
    expect(gaugeFraction(56)).toBe(1);
  });
});
import Image from "next/image";
import type { Service } from "@/content/schemas";
import { cn } from "@/lib/cn";
import { ChatPreview } from "./ChatPreview";

type Props = Service & { className?: string };

/**
 * One card in the services carousel. `media.kind` picks the layout:
 * - photo: full-bleed photo behind a white title (a light top scrim keeps
 *   the title readable on bright photos);
 * - product: product shot under the title in a 406x341 cover frame (as in
 *   Figma), bleeding off the right edge;
 * - chat: phone mockup cut off by the card bottom, chat panel on top.
 */
export function ServiceCard({ title, media, className }: Props) {
  const onPhoto = media.kind === "photo";
  return (
    <article
      className={cn(
        "relative isolate h-service-h w-service-w overflow-hidden rounded-card bg-surface",
        className,
      )}
    >
      {media.kind === "photo" ? (
        <>
          <Image
            src={media.image.src}
            alt={media.image.alt}
            fill
            sizes="(min-width: 64rem) 24rem, 21rem"
            className="-z-10 object-cover"
          />
          <div
            aria-hidden
            className="absolute inset-x-0 top-0 -z-10 h-2/5 bg-linear-to-b from-black/40 to-transparent"
          />
        </>
      ) : null}

      <h3
        className={cn(
          "px-6 pt-8 text-center text-card-heading font-normal",
          onPhoto ? "text-white" : "text-heading",
        )}
      >
        {title}
      </h3>

      {media.kind === "product" ? (
        <Image
          src={media.image.src}
          alt={media.image.alt}
          width={media.image.width}
          height={media.image.height}
          sizes="26rem"
          className="absolute top-60.25 left-2.25 h-85.25 w-101.5 max-w-none object-cover"
        />
      ) : null}

      {media.kind === "chat" ? (
        <>
          <Image
            src={media.image.src}
            alt={media.image.alt}
            width={media.image.width}
            height={media.image.height}
            sizes="20rem"
            className="absolute top-phone-top left-1/2 h-auto w-phone-w max-w-none -translate-x-1/2"
          />
          <ChatPreview
            chat={media.chat}
            className="absolute right-4.5 bottom-chat-bottom"
          />
        </>
      ) : null}
    </article>
  );
}
import type { HighlightCard } from "@/content/schemas";
import { cn } from "@/lib/cn";

type Props = {
  cards: readonly HighlightCard[];
  className?: string;
};

// Fixed design widths that may shrink on very narrow screens (320).
const card =
  "min-w-0 shrink rounded-panel bg-surface p-highlight-pad shadow-raised text-stat-title font-medium text-heading-strong";

/**
 * Stat cards floating over a program photo (sleep): a metrics card
 * ("Olivia Gomes — 78 Normal · 89.5% Progress") and a progress card
 * ("Your profile — 82%"). Decorative content, but real text, so it stays
 * readable for assistive tech. Positioned by the parent section.
 */
export function HighlightCards({ cards, className }: Props) {
  return (
    <ul
      className={cn(
        "flex max-w-[calc(100%-0.5rem)] items-stretch gap-highlight-gap",
        className,
      )}
    >
      {cards.map((item) =>
        item.kind === "metrics" ? (
          <li key={item.id} className={cn(card, "w-highlight-metrics")}>
            <p className="border-b border-dashed border-border pb-3">
              {item.title}
            </p>
            <dl className="mt-3 flex flex-wrap gap-x-highlight-stat-gap gap-y-1 lg:mt-4">
              {item.metrics.map((metric) => (
                <div
                  key={metric.label}
                  className="flex items-baseline gap-2 lg:gap-3"
                >
                  <dt className="sr-only">{metric.label}</dt>
                  <dd className="text-stat font-normal text-ink-900">
                    {metric.value}
                  </dd>
                  <dd
                    aria-hidden
                    className="text-stat-label font-normal text-accent"
                  >
                    {metric.label}
                  </dd>
                </div>
              ))}
            </dl>
          </li>
        ) : (
          <li key={item.id} className={cn(card, "w-highlight-progress")}>
            <p>{item.title}</p>
            <div
              role="progressbar"
              aria-label={item.title}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={item.percent}
              className="relative mt-7 h-1.5 overflow-hidden rounded-full bg-(image:--gradient-bmi)"
            >
              {/* Full-width gradient; the unfilled rest is covered. */}
              <div
                className="absolute inset-y-0 right-0 bg-border"
                style={{ width: `${100 - item.percent}%` }}
              />
            </div>
            <p
              aria-hidden
              className="mt-1.5 text-stat-label font-normal text-accent"
            >
              {item.percent}%
            </p>
          </li>
        ),
      )}
    </ul>
  );
}

