import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import { homeContent } from "@/content/mock";
import { BmiCalculator } from "./BmiCalculator";
import { toBmiProps } from "./to-bmi-props";

const { programId: _programId, ...props } = toBmiProps(homeContent);

const imperial = (heightFt: string, heightIn: string, weight: string) => ({
  unit: "imperial" as const,
  heightFt,
  heightIn,
  heightCm: "",
  weight,
});

const meta = {
  title: "Sections/BMI calculator",
  component: BmiCalculator,
  args: props,
  parameters: { layout: "fullscreen" },
  globals: { viewport: { value: "board1440", isRotated: false } },
  decorators: [
    (Story) => (
      <div className="px-gutter py-10">
        <Story />
      </div>
    ),
  ],
} satisfies Meta<typeof BmiCalculator>;

export default meta;
type Story = StoryObj<typeof meta>;

/** C9: empty inputs, "—" score, Calculate disabled until the input is valid. */
export const Initial: Story = {};

/** Valid input, not yet calculated: the button is enabled. */
export const ReadyToCalculate: Story = {
  args: { defaultInput: imperial("5", "7", "150") },
};

/** Out-of-range value: message under the field, button stays disabled. */
export const InvalidInput: Story = {
  args: { defaultInput: imperial("12", "0", "150") },
};

export const ResultHealthyWoman: Story = {
  args: { defaultInput: imperial("5", "7", "150"), defaultCalculated: true },
};

/** C6: the sentence names the chosen sex; the number is the same. */
export const ResultHealthyMan: Story = {
  args: {
    defaultInput: imperial("5", "7", "150"),
    defaultSex: "male",
    defaultCalculated: true,
  },
};

export const ResultUnderweight: Story = {
  args: { defaultInput: imperial("5", "9", "115"), defaultCalculated: true },
};

export const ResultOverweight: Story = {
  args: { defaultInput: imperial("5", "9", "180"), defaultCalculated: true },
};

export const ResultObese: Story = {
  args: { defaultInput: imperial("5", "4", "190"), defaultCalculated: true },
};

/** Metric units (cm / kg). */
export const MetricResult: Story = {
  args: {
    defaultInput: {
      unit: "metric",
      heightFt: "",
      heightIn: "",
      heightCm: "180",
      weight: "90",
    },
    defaultCalculated: true,
  },
};

/** Mobile board: one card, gauge on top, result sentence under the button. */
export const MobileInitial: Story = {
  globals: { viewport: { value: "board375", isRotated: false } },
};
export const MobileResult: Story = {
  ...ResultHealthyWoman,
  globals: { viewport: { value: "board375", isRotated: false } },
};

/** Hover / pressed on Calculate (same Button states as elsewhere). */
export const CalculateHover: Story = {
  ...ReadyToCalculate,
  parameters: { pseudo: { hover: ["button[type=submit]"] } },
};
export const CalculatePressed: Story = {
  ...ReadyToCalculate,
  parameters: { pseudo: { active: ["button[type=submit]"] } },
};
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { useState } from "react";
import { describe, expect, it } from "vitest";
import { NumberField } from "./number-field";
import { RadioPill } from "./radio-pill";
import { SegmentedControl } from "./segmented-control";

function Units() {
  const [value, setValue] = useState<"imperial" | "metric">("imperial");
  return (
    <SegmentedControl
      label="Units"
      value={value}
      onChange={setValue}
      options={[
        { value: "imperial", label: "ft / lbs" },
        { value: "metric", label: "cm / kg" },
      ]}
    />
  );
}

describe("SegmentedControl", () => {
  it("is a radio group that changes on click and with arrow keys", async () => {
    const user = userEvent.setup();
    render(<Units />);
    expect(screen.getByRole("group", { name: "Units" })).toBeInTheDocument();
    const imperial = screen.getByRole("radio", { name: "ft / lbs" });
    const metric = screen.getByRole("radio", { name: "cm / kg" });
    expect(imperial).toBeChecked();
    await user.click(screen.getByText("cm / kg"));
    expect(metric).toBeChecked();
    await user.keyboard("{ArrowLeft}");
    expect(imperial).toBeChecked();
  });
});

function Field({ initial = "" }: { initial?: string }) {
  const [value, setValue] = useState(initial);
  return (
    <NumberField
      label="Weight"
      unit="lbs"
      value={value}
      onChange={setValue}
      min={45}
      max={700}
      incrementLabel="Increase weight"
      decrementLabel="Decrease weight"
    />
  );
}

describe("NumberField", () => {
  it("accepts typing and steps with the buttons within bounds", async () => {
    const user = userEvent.setup();
    render(<Field initial="699" />);
    const input = screen.getByRole("spinbutton", { name: "Weight" });
    await user.click(screen.getByRole("button", { name: "Increase weight" }));
    await user.click(screen.getByRole("button", { name: "Increase weight" }));
    expect(input).toHaveValue(700);
    await user.clear(input);
    await user.type(input, "150");
    expect(input).toHaveValue(150);
  });

  it("starts from the minimum when empty", async () => {
    const user = userEvent.setup();
    render(<Field />);
    await user.click(screen.getByRole("button", { name: "Decrease weight" }));
    expect(screen.getByRole("spinbutton", { name: "Weight" })).toHaveValue(45);
  });

  it("announces errors", () => {
    render(
      <NumberField
        label="Height"
        unit="cm"
        value="40"
        onChange={() => {}}
        error="Enter 90–250 cm"
        incrementLabel="+"
        decrementLabel="-"
      />,
    );
    const input = screen.getByRole("spinbutton", { name: "Height" });
    expect(input).toHaveAttribute("aria-invalid", "true");
    expect(input).toHaveAccessibleDescription("Enter 90–250 cm");
  });
});

describe("RadioPill", () => {
  it("behaves as a native radio", async () => {
    const user = userEvent.setup();
    function Sex() {
      const [value, setValue] = useState("female");
      return (
        <fieldset>
          <legend>Sex</legend>
          {["male", "female"].map((option) => (
            <RadioPill
              key={option}
              name="sex"
              value={option}
              checked={value === option}
              onChange={() => setValue(option)}
            >
              {option}
            </RadioPill>
          ))}
        </fieldset>
      );
    }
    render(<Sex />);
    expect(screen.getByRole("radio", { name: "female" })).toBeChecked();
    await user.click(screen.getByText("male"));
    expect(screen.getByRole("radio", { name: "male" })).toBeChecked();
  });
});
