          <div
            aria-hidden
            className="absolute inset-x-0 top-0 -z-10 h-2/5 bg-linear-to-b from-black/40 to-transparent"
          />
        </>
      ) : null}

      <h3
        className={cn(
          "px-6 pt-8 text-center text-card-heading font-normal",
          onPhoto ? "text-white" : "text-heading",
